/bin/bash -c "python - <<'PY'
import numpy as np
x=np.load('source_pixels.npz')['rgb']
# inspect region 90:180 y 45:90 frame0 to locate ball/mallet colors and sample base. Print color at every strong saturation pixel grid with exact RGB
im=x[0]
for y in range(45,90,2):
 out=[]
 for xx in range(90,180,4):
  r,g,b=map(int,im[y,xx]);
  if max(r,g,b)-min(r,g,b)>25: out.append(f'{xx}:{r},{g},{b}')
 print(y,' '.join(out))
PY"

